-- Apply after the existing foundation and payment setup scripts. No user data is deleted.
begin;
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), ride_id uuid references public.rides, reviewer_id uuid references public.users, reviewee_id uuid references public.users, rating integer check(rating between 1 and 5), comment text, unique(ride_id,reviewer_id,reviewee_id), created_at timestamptz not null default now());
alter table public.reviews enable row level security;
revoke all on public.reviews from anon, authenticated;
grant select,insert,update,delete on public.reviews to authenticated;
grant all on public.reviews to service_role;
create policy "admin_access" on public.reviews for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references public.users, title text not null, message text not null, type text, read boolean not null default false, created_at timestamptz not null default now());
alter table public.notifications enable row level security;
revoke all on public.notifications from anon, authenticated;
grant select,insert,update,delete on public.notifications to authenticated;
grant all on public.notifications to service_role;
create policy "admin_access" on public.notifications for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.driver_verification (id uuid primary key default gen_random_uuid(), user_id uuid unique references public.users, license_number text, license_photo text, vehicle_type text, vehicle_number text, vehicle_model text, vehicle_color text, vehicle_photo text, vehicle_docs text[], id_card_photo text, college_id text, verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected')), rejection_reason text, verified_by uuid references public.users, verified_at timestamptz, submitted_at timestamptz, created_at timestamptz not null default now());
alter table public.driver_verification enable row level security;
revoke all on public.driver_verification from anon, authenticated;
grant select,insert,update,delete on public.driver_verification to authenticated;
grant all on public.driver_verification to service_role;
create policy "admin_access" on public.driver_verification for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.live_locations (id uuid primary key default gen_random_uuid(), ride_id uuid unique references public.rides, driver_id uuid references public.users, location jsonb, speed double precision, updated_at timestamptz default now(), created_at timestamptz not null default now());
alter table public.live_locations enable row level security;
revoke all on public.live_locations from anon, authenticated;
grant select,insert,update,delete on public.live_locations to authenticated;
grant all on public.live_locations to service_role;
create policy "admin_access" on public.live_locations for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.sos_alerts (id uuid primary key default gen_random_uuid(), user_id uuid references public.users, ride_id uuid references public.rides, location jsonb, message text, status text default 'active' check(status in ('active','resolved')), created_at timestamptz not null default now());
alter table public.sos_alerts enable row level security;
revoke all on public.sos_alerts from anon, authenticated;
grant select,insert,update,delete on public.sos_alerts to authenticated;
grant all on public.sos_alerts to service_role;
create policy "admin_access" on public.sos_alerts for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), ride_id uuid references public.rides, sender_id uuid references public.users, message text not null, attachment_url text, created_at timestamptz not null default now());
alter table public.messages enable row level security;
revoke all on public.messages from anon, authenticated;
grant select,insert,update,delete on public.messages to authenticated;
grant all on public.messages to service_role;
create policy "admin_access" on public.messages for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.banned_users (id uuid primary key default gen_random_uuid(), user_id uuid unique references public.users, reason text, banned_by uuid references public.users, banned_at timestamptz default now(), created_at timestamptz not null default now());
alter table public.banned_users enable row level security;
revoke all on public.banned_users from anon, authenticated;
grant select,insert,update,delete on public.banned_users to authenticated;
grant all on public.banned_users to service_role;
create policy "admin_access" on public.banned_users for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.admin_logs (id uuid primary key default gen_random_uuid(), admin_id uuid references public.users, action text not null, target_user_id uuid references public.users, details jsonb, created_at timestamptz not null default now());
alter table public.admin_logs enable row level security;
revoke all on public.admin_logs from anon, authenticated;
grant select,insert,update,delete on public.admin_logs to authenticated;
grant all on public.admin_logs to service_role;
create policy "admin_access" on public.admin_logs for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.saved_routes (id uuid primary key default gen_random_uuid(), user_id uuid references public.users, label text, from_location jsonb not null, to_location jsonb not null, created_at timestamptz not null default now());
alter table public.saved_routes enable row level security;
revoke all on public.saved_routes from anon, authenticated;
grant select,insert,update,delete on public.saved_routes to authenticated;
grant all on public.saved_routes to service_role;
create policy "admin_access" on public.saved_routes for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.announcements (id uuid primary key default gen_random_uuid(), title text not null, body text not null, severity text default 'info', audience text default 'all', active boolean default true, created_by uuid references public.users, created_at timestamptz not null default now());
alter table public.announcements enable row level security;
revoke all on public.announcements from anon, authenticated;
grant select,insert,update,delete on public.announcements to authenticated;
grant all on public.announcements to service_role;
create policy "admin_access" on public.announcements for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.ride_reports (id uuid primary key default gen_random_uuid(), ride_id uuid references public.rides, reporter_id uuid references public.users, reported_user_id uuid references public.users, reason text not null, status text default 'open', created_at timestamptz not null default now());
alter table public.ride_reports enable row level security;
revoke all on public.ride_reports from anon, authenticated;
grant select,insert,update,delete on public.ride_reports to authenticated;
grant all on public.ride_reports to service_role;
create policy "admin_access" on public.ride_reports for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create table if not exists public.support_messages (id uuid primary key default gen_random_uuid(), user_id uuid references public.users, admin_id uuid references public.users, message text not null, sender_type text check(sender_type in ('user','admin')), is_read boolean default false, attachment_url text, created_at timestamptz not null default now());
alter table public.support_messages enable row level security;
revoke all on public.support_messages from anon, authenticated;
grant select,insert,update,delete on public.support_messages to authenticated;
grant all on public.support_messages to service_role;
create policy "admin_access" on public.support_messages for all to authenticated using ((select private.is_approved_admin())) with check ((select private.is_approved_admin()));
create index on public.saved_routes(user_id);
create policy owner_read on public.saved_routes for select to authenticated using (user_id=(select auth.uid()));
create policy owner_insert on public.saved_routes for insert to authenticated with check (user_id=(select auth.uid()));
create policy owner_update on public.saved_routes for update to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
create policy owner_delete on public.saved_routes for delete to authenticated using (user_id=(select auth.uid()));
create index on public.support_messages(user_id);
create policy owner_read on public.support_messages for select to authenticated using (user_id=(select auth.uid()));
create policy owner_insert on public.support_messages for insert to authenticated with check (user_id=(select auth.uid()) and sender_type='user' and admin_id is null);
create index on public.driver_verification(user_id);
create policy owner_read on public.driver_verification for select to authenticated using (user_id=(select auth.uid()));
create policy owner_insert on public.driver_verification for insert to authenticated with check (user_id=(select auth.uid()) and verification_status='pending' and verified_by is null and verified_at is null);
create policy owner_update on public.driver_verification for update to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()) and verification_status='pending' and verified_by is null and verified_at is null);
create index on public.sos_alerts(user_id);
create policy owner_read on public.sos_alerts for select to authenticated using (user_id=(select auth.uid()));
create policy owner_insert on public.sos_alerts for insert to authenticated with check (user_id=(select auth.uid()) and status='active');
create index on public.ride_reports(reporter_id);
create policy owner_read on public.ride_reports for select to authenticated using (reporter_id=(select auth.uid()));
create policy owner_insert on public.ride_reports for insert to authenticated with check (reporter_id=(select auth.uid()) and status='open');
create index on public.notifications(user_id);
create policy owner_read on public.notifications for select to authenticated using (user_id=(select auth.uid()));
grant update(read) on public.notifications to authenticated;
create policy owner_read_update on public.notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create or replace function private.ride_member(trip uuid) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and (exists(select 1 from public.rides where id=trip and driver_id=auth.uid()) or exists(select 1 from public.bookings where ride_id=trip and rider_id=auth.uid() and status in ('confirmed','completed')));
$$;
revoke all on function private.ride_member(uuid) from public,anon;
grant execute on function private.ride_member(uuid) to authenticated;
create policy passenger_read on public.rides for select to authenticated using(private.ride_member(id));
create policy participant_read on public.messages for select to authenticated using(private.ride_member(ride_id));
create policy participant_send on public.messages for insert to authenticated with check(sender_id=(select auth.uid()) and private.ride_member(ride_id));
create policy participant_location on public.live_locations for select to authenticated using(private.ride_member(ride_id));
create policy driver_location on public.live_locations for insert to authenticated with check(driver_id=(select auth.uid()) and exists(select 1 from public.rides where id=ride_id and driver_id=(select auth.uid()) and status='in_progress'));
create policy driver_location_update on public.live_locations for update to authenticated using(driver_id=(select auth.uid())) with check(driver_id=(select auth.uid()) and exists(select 1 from public.rides where id=ride_id and driver_id=(select auth.uid()) and status='in_progress'));
create policy published_announcements on public.announcements for select to authenticated using(active and (audience='all' or audience=case (select user_type from public.users where id=(select auth.uid())) when 'student' then 'students' when 'driver' then 'drivers' when 'admin' then 'admins' else '' end));
create policy review_read on public.reviews for select to authenticated using(reviewer_id=(select auth.uid()) or reviewee_id=(select auth.uid()));
create policy review_write on public.reviews for insert to authenticated with check(reviewer_id=(select auth.uid()) and reviewer_id<>reviewee_id and private.ride_member(ride_id) and exists(select 1 from public.rides where id=ride_id and status='completed'));

revoke update on public.notifications from authenticated; grant update(read) on public.notifications to authenticated;
revoke update on public.driver_verification from authenticated; grant update(license_number,license_photo,vehicle_type,vehicle_number,vehicle_model,vehicle_color,vehicle_photo,vehicle_docs,id_card_photo,college_id,submitted_at) on public.driver_verification to authenticated;
create or replace function public.user_stats(target uuid) returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('total_bookings',(select count(*) from public.bookings where rider_id=target),'total_rides_offered',(select count(*) from public.rides where driver_id=target),'total_spent',(select coalesce(sum(total_price),0) from public.bookings where rider_id=target and payment_status='paid'),'total_earned',(select coalesce(sum(b.total_price),0) from public.bookings b join public.rides r on r.id=b.ride_id where r.driver_id=target and b.payment_status='paid' and b.status='completed'),'avg_rating',(select coalesce(avg(rating),0) from public.reviews where reviewee_id=target),'ratings_count',(select count(*) from public.reviews where reviewee_id=target),'last_ride_at',(select max(departure_time) from public.rides where driver_id=target),'last_booking_at',(select max(created_at) from public.bookings where rider_id=target)) where target=auth.uid();
$$;
revoke all on function public.user_stats(uuid) from public,anon;
grant execute on function public.user_stats(uuid) to authenticated;

-- One transaction owns lifecycle state and associated booking completion.
create or replace function private.transition_ride(trip uuid, next_status text) returns public.rides
language plpgsql security definer set search_path='' as $$
declare current_trip public.rides;
begin
 select * into current_trip from public.rides where id=trip for update;
 if auth.uid() is null or current_trip.id is null or (current_trip.driver_id<>auth.uid() and not private.is_approved_admin()) then raise exception 'Ride access denied' using errcode='42501'; end if;
 if not ((current_trip.status='active' and next_status in ('in_progress','cancelled')) or (current_trip.status='in_progress' and next_status in ('completed','cancelled'))) then raise exception 'Invalid ride transition'; end if;
 if next_status='cancelled' and exists(select 1 from public.bookings where ride_id=trip and payment_status='paid' and status<>'cancelled') then raise exception 'Refund paid bookings before cancelling this ride'; end if;
 update public.rides set status=next_status where id=trip returning * into current_trip;
 if next_status='completed' then update public.bookings set status='completed' where ride_id=trip and status='confirmed'; end if;
 if next_status='cancelled' then update public.bookings set status='cancelled' where ride_id=trip and status in ('pending','confirmed'); end if;
 return current_trip;
end $$;
revoke all on function private.transition_ride(uuid,text) from public,anon;
grant execute on function private.transition_ride(uuid,text) to authenticated;
create or replace function public.transition_ride(trip uuid,next_status text) returns public.rides language sql security invoker set search_path='' as $$ select private.transition_ride(trip,next_status); $$;
revoke all on function public.transition_ride(uuid,text) from public,anon;
grant execute on function public.transition_ride(uuid,text) to authenticated;

notify pgrst, 'reload schema';
commit;